class Ship {
    // 배송비 규칙을 한곳에 모은 공통 모듈이에요.
    static int fee(int price) {
        // 이 금액 이상이면 배송비가 없어요.
        int free = 30000;
        // 기본 배송비예요.
        int cost = 3000;
        // 기준 이상이면 0원, 아니면 기본 배송비를 돌려줘요.
        if (price >= free) {
            return 0;
        }
        return cost;
    }
}

class Main {
    public static void main(String[] args) {
        // 고객이 담은 상품 금액이에요.
        int price = 40000;
        // 주문 단계는 공통 모듈을 불러요.
        // 다른 클래스의 static 메서드는 클래스 이름 뒤에 점을 찍어 불러요.
        int orderFee = Ship.fee(price);
        // 장바구니 단계는 예전 규칙을 베껴 와서 따로 계산해요.
        int cartFee = 3000;
        if (price >= 50000) {
            cartFee = 0;
        }
        // 프로세스 순서대로 장바구니, 주문 배송비를 출력해요.
        System.out.println("장바구니 배송비: " + cartFee);
        System.out.println("주문 배송비: " + orderFee);
    }
}

