class Main {
    // 클래스에 둔 static 변수라 모든 메서드가 같이 써요.
    static int rate = 10;

    // 평소 할인가예요. 전역 rate를 읽어요.
    static int normal(int price) {
        return price - price * rate / 100;
    }

    // 행사 할인가예요. 행사 할인율 event를 인자로 받아요.
    static int sale(int price, int event) {
        // 받은 할인율을 전역 rate에 넣어 써요.
        rate = event;
        return price - price * rate / 100;
    }

    public static void main(String[] args) {
        // 상품 가격과 행사 할인율이에요.
        int price = 20000;
        int event = 30;
        // 행사 전, 행사, 행사 뒤 순서로 가격을 봐요.
        System.out.println("평소: " + normal(price));
        System.out.println("행사: " + sale(price, event));
        System.out.println("다시 평소: " + normal(price));
    }
}

